(v.indicators.support)} / ${"%.6f".format(v.indicators.resistance)}")}};item{var q by remember{mutableStateOf("")};OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),label={Text("COİN ARA")},singleLine=true,trailingIcon={TextButton(onClick={if(q.isNotBlank())vm.selectSymbol(if(q.uppercase().endsWith("USDT"))q.uppercase() else q.uppercase()+"USDT")}){Text("AÇ")}})};item{Text("BINANCE MOVER · ${vm.brain.uppercase()}",color=Color.White,fontWeight=FontWeight.Bold)};items(vm.movers.take(25)){m->Row(Modifier.fillMaxWidth().clickable{vm.selectSymbol(m.symbol)}.background(Card,RoundedCornerShape(12.dp)).padding(12.dp),horizontalArrangement=Arrangement.SpaceBetween){Text(m.symbol,color=Color.White);Text("${"%.2f".format(m.changePct)}%",color=if(m.changePct>=0)Green else Red);Text("S ${"%.0f".format(m.score)}",color=Muted)}}}else if(tab==1){item{Panel("ZAMAN DİLİMLERİ ANALİZİ"){v.timeframes.forEach{(k,x)->Stat(k,x)}}};item{Panel("DERİN TEKNİK"){Stat("Karar",v.decision);Stat("Karakter",v.character);Stat("Gerekçe",v.reason)}}}else{item{Panel("İŞLEM DURUMU"){Text(v.decision,color=Color.White,fontWeight=FontWeight.Bold);Text(v.reason,color=Muted)}};item{Panel("SEVİYELER"){Stat("Giriş","${"%.6f".format(v.entryLow)} — ${"%.6f".format(v.entryHigh)}");Stat("Fiyat","%.6f".format(v.price));v.targets.forEachIndexed{i,t->Stat("Hedef ${i+1}","%.6f".format(t),true)};Stat("Invalidation","%.6f".format(v.invalidation),false);Stat("Emergency","%.6f".format(v.emergency),false)}};item{Panel("POZİSYON"){Stat("Pozisyon","${"%.2f".format(v.positionUsdt)} USDT");Stat("Risk / Kazanç","1 : ${"%.2f".format(v.rewardRisk)}")}}}}}
